/**
 * Where the training images of every math class come from.
 *
 *   - digits   : MNIST (+ the few HASY digits)
 *   - letters  : EMNIST ByClass (case-sensitive; classes that look the same in both cases are merged)
 *   - symbols  : HASYv2 (Thiemann et al.), 168k handwritten symbols from write-math.com
 *   - drawn    : generated by src/ml/syntheticSymbols.ts (HASY has no '=', '(' or ')')
 */
import { OperatorSymbol } from '../../src/ml/syntheticSymbols';

