/** Classes drawn from vector strokes by src/ml/syntheticSymbols.ts (mixed in with HASY when it has some). */
export const DRAWN_SOURCES: Record<string, OperatorSymbol> = {
  '+': '+',
  '-': '-',
  '/': '/',
  '=': '=',
  '(': '(',
  ')': ')',
  '!': '!',
  '<': '<',
  '>': '>',
};

/** EMNIST ByClass label (0-9, A-Z = 10-35, a-z = 36-61) -> math class, or undefined if unused. */
export function emnistByClassToChar(label: number): string | undefined {
  if (label < 10) return String(label);
  const upper = label < 36;
  const letter = String.fromCharCode((upper ? 65 : 97) + (upper ? label - 10 : label - 36));
  // Vertical bars: indistinguishable from 1 and |
  if (letter === 'I' || letter === 'l') return undefined;
  const lower = letter.toLowerCase();
  // Same shape in both cases: one class, written in lower case
  if ('cjkmopsuvwxyz'.includes(lower)) return lower;
  return letter;
}
